<template><span><template v-for="(part,index) in parts" :key="index"><span v-if="!part.id">{{part.text}}</span><el-popover v-else trigger="click" placement="left" :width="560" @show="load(part.id)"><template #reference><el-link type="primary" @mousedown.stop>{{part.text}}</el-link></template><div v-loading="loading" class="chat-talent-profile"><h3>译员资料</h3><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-descriptions v-else-if="profile" :column="2" border size="small"><el-descriptions-item label="姓名">{{profile.full_name}}</el-descriptions-item><el-descriptions-item label="资源编号">{{profile.resource_code||'-'}}</el-descriptions-item><el-descriptions-item label="中文姓名">{{profile.chinese_name||'-'}}</el-descriptions-item><el-descriptions-item label="外文姓名">{{profile.english_name||'-'}}</el-descriptions-item><el-descriptions-item label="昵称">{{profile.nickname||'-'}}</el-descriptions-item><el-descriptions-item label="性别">{{profile.gender||'-'}}</el-descriptions-item><el-descriptions-item label="母语">{{languages('native')}}</el-descriptions-item><el-descriptions-item label="外语">{{languages('foreign')}}</el-descriptions-item><el-descriptions-item label="简历路径" :span="2">{{profile.resume_path||'-'}}</el-descriptions-item></el-descriptions></div></el-popover></template></span></template>
<script setup>
import {computed,ref} from 'vue'
import api from '@/api'
const props=defineProps({text:{type:String,default:''}})
const parts=computed(()=>{const out=[],pattern=/\[([^\]\n]+)\]\(talent:\/\/([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})\)/gi;let last=0;for(const match of props.text.matchAll(pattern)){if(match.index>last)out.push({text:props.text.slice(last,match.index)});out.push({text:match[1],id:match[2]});last=match.index+match[0].length}if(last<props.text.length)out.push({text:props.text.slice(last)});return out})
const profile=ref(),loading=ref(false),error=ref('');let seq=0
async function load(id){const current=++seq;profile.value=null;loading.value=true;error.value='';try{const result=await api.get(`/talent-options/profile/${id}`);if(current===seq)profile.value=result}catch(e){if(current===seq)error.value=e.detail||'译员资料加载失败'}finally{if(current===seq)loading.value=false}}
const languages=role=>(profile.value?.language_skills||[]).filter(row=>row.role===role).map(row=>row.label).join('、')||'-'
</script>
<style scoped>.chat-talent-profile{max-height:min(560px,calc(100vh - 120px));overflow:auto;white-space:normal;overflow-wrap:anywhere}.chat-talent-profile h3{margin-top:0}.el-link{vertical-align:baseline;font:inherit}</style>
